package com.example.activeperception.acquire

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Golden replay tests for [NelderMead] against the Python source of truth.
 *
 * Traces were generated by sense/nm_golden_gen.py driving the REAL sense/nelder_mead.py
 * (class NM) with synthetic objectives; observe() is fed the recorded values, so the test
 * checks the state machine alone, not the objective. uMax = 4.0 matches the 5x5
 * simulation the goldens ran on. Between them the three traces exercise every branch:
 * reflect accept, expand, outside/inside contraction, shrink, and both TOL and MAXF exits.
 */
class NelderMeadTest {

    private class Golden(
        val u0: DoubleArray, val meanI: Double,
        val proposals: DoubleArray,  // (isoStops, shutterStops) pairs, interleaved
        val fvals: DoubleArray,
        val best: DoubleArray, val nFeval: Int,
    )

    private fun replay(g: Golden) {
        val nm = NelderMead(g.u0, g.meanI, 4.0)
        for (k in g.fvals.indices) {
            val u = nm.propose()!!
            val u2 = nm.propose()!!  // idempotent: a repeated call must not advance state
            assertEquals("step $k iso", g.proposals[2 * k], u[0], 1e-9)
            assertEquals("step $k shutter", g.proposals[2 * k + 1], u[1], 1e-9)
            assertEquals(u[0], u2[0], 0.0)
            assertEquals(u[1], u2[1], 0.0)
            nm.observe(g.fvals[k])
        }
        assertTrue(nm.converged)
        assertNull(nm.propose())
        assertEquals(g.nFeval, nm.nFeval)
        assertEquals(g.best[0], nm.best()[0], 1e-9)
        assertEquals(g.best[1], nm.best()[1], 1e-9)
    }

    @Test fun darkBowl() = replay(DARK_BOWL)       // meanI<128 branch of the initial simplex
    @Test fun brightBowl() = replay(BRIGHT_BOWL)   // meanI>=128 branch, expand steps
    @Test fun rippleShrink() = replay(RIPPLE_SHRINK)  // shrink branch + MAXF exit

    @Test fun snapMatchesPythonTo5() {
        // (u, cell) golden pairs from to5 in sense/nelder_mead.py; Python round() is
        // half-to-even, which Math.rint reproduces (round(2.5) = 2, round(3.5) = 4)
        assertEquals(2, NelderMead.snapToGrid(doubleArrayOf(0.5, 1.5), 5, 5))
        assertEquals(14, NelderMead.snapToGrid(doubleArrayOf(2.5, 3.5), 5, 5))
        assertEquals(4, NelderMead.snapToGrid(doubleArrayOf(-0.2, 4.7), 5, 5))
        assertEquals(8, NelderMead.snapToGrid(doubleArrayOf(1.4999999, 2.5000001), 5, 5))
        assertEquals(20, NelderMead.snapToGrid(doubleArrayOf(4.0, 0.0), 5, 5))
        assertEquals(20, NelderMead.snapToGrid(doubleArrayOf(3.5000001, 0.4999999), 5, 5))
        assertEquals(7, NelderMead.snapToGrid(doubleArrayOf(1.3, 2.1), 5, 5))
    }

    @Test fun snapParameterizedGridClipsAndIndexes() {
        assertEquals(8, NelderMead.snapToGrid(doubleArrayOf(1.5, 2.6), 3, 3))  // rint(1.5)=2; 2.6 clips to 2
        assertEquals(0, NelderMead.snapToGrid(doubleArrayOf(-0.4, 0.5), 3, 3)) // negative clips to 0; rint(0.5)=0
        assertEquals(5, NelderMead.snapToGrid(doubleArrayOf(1.2, 1.9), 3, 3))  // interior: cell = 1*3+2
    }

